3	/**
4	 * A key face as SVG.
5	 *
6	 * SVG, because it needs no rasterizer and no native module in a package
7	 * the Marketplace installs; base64, because Stream Deck 7.5 on Windows
8	 * rejects a raw SVG string despite the documentation. 144 square is the
9	 * @2x size; the software scales it to any key.
10	 *
11	 * The palette is the app's own: celadon for a key that moves the run,
12	 * kiln for a refusal and for undo, the muted ink for a key with nothing
13	 * to do. System sans, since a font in an SVG would have to travel as
14	 * base64 on every redraw.
15	 *
16	 * The grounds carry the family, because an edge 3px wide is not enough to
17	 * tell six kinds of key apart across a deck at arm's length: celadon-tinted
18	 * where the key moves the run, kiln-tinted for undo and for a refusal,
19	 * neutral and a shade lighter for the furniture, near-black under a readout
20	 * so the number floats. Every ink clears 4.5:1 on its own ground and every
21	 * `when` line clears 3:1, which `face.test.ts` checks rather than trusts.
22	 *
23	 * `stroke` is the frame's width, and `quiet` the color of the `when` line
24	 * and the corner glyph where the edge is too dark to read them in - a
25	 * readout, the furniture, and a key with nothing to do, whose frames are
26	 * hairlines and near-grounds rather than accents.
27	 */
28	const TONE: Record<Tone, { ground: string; ink: string; edge: string; stroke?: number; quiet?: string }> = {
29	  live: { ground: "#243d31", ink: "#e7eae6", edge: "#8cc3a6" },
30	  dim: { ground: "#1b201d", ink: "#8d958f", edge: "#2f3733", quiet: "#8d958f" },
31	  refuse: { ground: "#33211a", ink: "#e7eae6", edge: "#dd8f63" },
32	  undo: { ground: "#3a2a1f", ink: "#e7eae6", edge: "#dd8f63" },
33	  deck: { ground: "#262b28", ink: "#e7eae6", edge: "#2f3733", quiet: "#8d958f" },
34	  readout: { ground: "#121413", ink: "#e7eae6", edge: "#2f3733", stroke: 1, quiet: "#8d958f" },
35	};
