1	/**
2	 * Everything the plugin decides, with nothing from the SDK in it.
3	 *
4	 * A key face is a function of what the plugin knows: whether it is
5	 * signed in, whether its socket is open, which runs are held, which is
6	 * pinned, and what that run last published. `reduce` moves the state on
7	 * one event at a time; the `*Face` functions read it. Keeping them pure
8	 * is what lets the twelve states a key can be in have a test each.
9	 */
10	
11	/**
12	 * What a deck may press, right now, in the pack's own words.
13	 *
14	 * Copied from `apps/web/src/run/offer.ts`: the plugin does not import
15	 * from `apps/web`, so this shape is mirrored rather than shared.
16	 */
17	export interface Offer {
18	  seq: number;
19	  /**
20	   * The one press the run is waiting on.
21	   *
22	   * `owed` is a threshold or a global roll the run owes, which a deck
23	   * presses like any other primary: the page decides what it turns into.
24	   */
25	  primary: { id: "roll" | "carry-on" | "close" | "enter" | "owed"; label: string; kind: string } | null;
26	  moves: Array<{ id: string; label: string }>;
27	  undo: { what: string } | null;
28	  /** Why a deck cannot press this, in words a key face can carry. */
29	  needsPage: string | null;
30	  presets: Array<{ kind: string; label: string; suggestions?: string[]; items?: number }>;
31	  /** The setups the run could hand out, empty where the run names no tool or is not live. */
32	  setups: Array<{ id: string; title: string }>;
33	  /** The counters and resources this run will take a change to, from a deck as from the page. */
34	  trackers: Array<{ id: string; kind: "counter" | "resource"; label: string; value: number; max: number | null }>;
35	  /** The clock a deck may pause, resume or stop, or nothing where the run keeps none. */
36	  clock: { id: string; label: string; status: "running" | "paused" | "done" } | null;
37	  /** Whether the run is rolling for itself rather than waiting on a press. */
38	  autoRoll: boolean;
39	  /** How the run would end if it were finished now, or nothing while it cannot be. */
40	  ending: { label: string } | null;
41	}
42	
43	export type SessionState = "none" | "expired" | "ok";
44	export type SocketState = "closed" | "connecting" | "open";
45	export interface HeldRun {
46	  id: string;
47	  name?: string;
48	  packTitle?: string;
49	}
50	export interface Snapshot {
51	  /** The run as the server knows it, which is where the pack's id travels. */
52	  run?: { id?: string; packId?: string };
53	  unit?: number;
54	  words?: { unit: string };
55	  score?: { text: string };
56	  latest?: { text: string } | null;
57	  clocks?: Array<{ id: string; label: string; kind: "timer" | "stopwatch"; seconds: number | null; status: string; elapsedMs: number }>;
58	  standings?: Array<{ name: string; points: number; place: number }>;
59	  counters?: Array<{ id: string; label: string; value: number }>;
60	  resources?: Array<{ id: string; label: string; value: number; max: number | null }>;
61	  at?: string;
62	  offer?: Offer;
63	}
64	export interface DeckState {
65	  session: SessionState;
66	  /** Whether the streamer has switched the deck on. No socket while false. */
67	  on: boolean;
68	  /** Whether the last time it went off, it was the idle timer rather than a press. */
69	  idleOff: boolean;
70	  socket: SocketState;
71	  runs: HeldRun[];
72	  any: boolean;
73	  pinned: string | null;
74	  attached: string | null;
75	  snapshot: Snapshot | null;
76	  flash: { ref: string; ok: boolean; say?: string; until: number } | null;
77	}
78	/**
79	 * How a face is drawn, by what the key is for rather than by how it feels.
80	 *
81	 * `live` is a key that moves the run - Next, Roll, Press - and it is the
82	 * only one that takes the celadon edge. `undo` is the same lit face with
83	 * the kiln edge, because taking a result back is the consequence the
84	 * second accent is for. `readout` is a Metric key, which is a number
85	 * rather than a button: the app's own ground, a hairline, and lit ink.
86	 * `deck` is the furniture - Connect, Run, Open, Apply setup - lit, but
87	 * without an accent claiming it does something to the run. `dim` and
88	 * `refuse` are states rather than families and belong to every key.
89	 */
90	export type Tone = "live" | "dim" | "refuse" | "undo" | "readout" | "deck";
91	export interface Face {
92	  title: string;
93	  tone: Tone;
94	  when?: string;
95	  /** 0-1, set only for a running timer clock so a dial's indicator can draw it. */
96	  fraction?: number;
97	}
98	export type PressTarget = { kind: "roll" } | { kind: "move"; id: string } | { kind: "answer"; preset: string; value: string };
99	export type MetricField = "score" | "unit" | "clock" | "latest" | "leader" | { counter: string } | { resource: string };
100	/** What a short press of an adjustable Metric key does: step it up by one, or put it at a number. */
101	export type MetricPress = { kind: "step" } | { kind: "set"; value: number };
102	/** The answer form of a press, which is how everything but the primary and undo goes over the wire. */
103	export type AnswerPress = { press: "answer"; answer: Record<string, unknown> };
104	export type DeckEvent =
105	  | { t: "session"; state: SessionState }
106	  | { t: "on"; on: boolean; idle?: boolean }
107	  | { t: "socket"; state: SocketState }
108	  | { t: "runs"; runs: HeldRun[]; any: boolean }
109	  | { t: "pin"; id: string | null }
110	  | { t: "snapshot"; snapshot: Snapshot }
111	  | { t: "drove"; ref: string; ok: boolean; say?: string; seq?: number }
112	  | { t: "tick" };
113	
114	const FLASH_MS = 3000;
115	
116	/** How long a connection that is holding nothing waits before closing itself. */
117	export const IDLE_OFF_MS = 30 * 60_000;
118	
119	export function initial(): DeckState {
120	  return {
121	    session: "none",
122	    on: false,
123	    idleOff: false,
124	    socket: "closed",
125	    runs: [],
126	    any: false,
127	    pinned: null,
128	    attached: null,
129	    snapshot: null,
130	    flash: null,
131	  };
132	}
133	
134	export function attachedRun(state: DeckState): string | null {
135	  if (state.pinned) return state.runs.some((r) => r.id === state.pinned) ? state.pinned : null;
136	  return state.runs.length === 1 ? state.runs[0]!.id : null;
137	}
138	
139	export function reduce(state: DeckState, event: DeckEvent, now: number): DeckState {
140	  switch (event.t) {
141	    case "session":
142	      return event.state === "ok" ? { ...state, session: "ok" } : { ...initial(), session: event.state, pinned: state.pinned };
143	    case "on":
144	      // Going off is a full stop: no socket, nothing held, nothing to draw
145	      // a number from. The pin is a preference, not a holding, and stays.
146	      return event.on
147	        ? { ...state, on: true, idleOff: false }
148	        : { ...state, on: false, idleOff: event.idle === true, socket: "closed", runs: [], attached: null, snapshot: null };
149	    case "socket":
150	      return event.state === "open"
151	        ? { ...state, socket: "open" }
152	        : { ...state, socket: event.state, runs: [], attached: null, snapshot: null };
153	    case "runs": {
154	      const next = { ...state, runs: event.runs, any: event.any };
155	      const attached = attachedRun(next);
156	      // A run that went away takes its numbers with it; a run that is
157	      // still here keeps them until the next snapshot lands.
158	      return { ...next, attached, snapshot: attached === state.attached ? state.snapshot : null };
159	    }
160	    case "pin": {
161	      const next = { ...state, pinned: event.id };
162	      const attached = attachedRun(next);
163	      return { ...next, attached, snapshot: attached === state.attached ? state.snapshot : null };
164	    }
165	    case "snapshot":
166	      return { ...state, snapshot: event.snapshot };
167	    case "drove": {
168	      const flash = { ref: event.ref, ok: event.ok, ...(event.say ? { say: event.say } : {}), until: now + FLASH_MS };
169	      // A `drove` verdict is the freshest seq source: the next press
170	      // should not carry a seq gone stale while it was in flight.
171	      if (event.seq === undefined || !state.snapshot?.offer) return { ...state, flash };
172	      return { ...state, flash, snapshot: { ...state.snapshot, offer: { ...state.snapshot.offer, seq: event.seq } } };
173	    }
174	    case "tick": {
175	      const expired = state.flash !== null && state.flash.until <= now;
176	      // Controller ruling 3: a dial redraws every second while a clock is
177	      // running, so its remaining time keeps moving between snapshots. An
178	      // idle deck has nothing that changes on the tick, so it stays the
179	      // same object and nothing redraws.
180	      const running = state.snapshot?.clocks?.some((c) => c.status === "running") ?? false;
181	      if (!expired && !running) return state;
182	      return expired ? { ...state, flash: null } : { ...state };
183	    }
184	  }
185	}
186	
187	/** What a key says about the run once the deck is signed in and switched on. */
188	function held(state: DeckState): Face | null {
189	  if (state.socket !== "open") return { title: "Offline", tone: "dim" };
190	  if (state.pinned && !state.runs.some((r) => r.id === state.pinned)) return { title: "That run has ended", tone: "dim" };
191	  if (state.runs.length === 0) return state.any ? { title: "No run open", tone: "dim" } : { title: "Not synced", tone: "dim" };
192	  if (!state.attached) return { title: "Pick a run", tone: "dim" };
193	  return null;
194	}
195	
196	/** The state every key shares before any of them has something of its own to say. */
197	function common(state: DeckState): Face | null {
198	  if (state.session === "none") return { title: "Sign in", tone: "dim" };
199	  if (state.session === "expired") return { title: "Sign in again", tone: "dim" };
200	  // A key that depends on the connection says to make it first: the state
201	  // on top, the thing to do about it beneath.
202	  if (!state.on) return { title: "Not connected", tone: "dim", when: "press Connect" };
203	  return held(state);
204	}
205	
206	/** The run a deck is following, named, or nothing. */
207	function attachedName(state: DeckState): Face | null {
208	  const run = state.runs.find((r) => r.id === state.attached);
209	  if (!run) return null;
210	  return { title: run.name ?? run.packTitle ?? run.id, tone: "deck", ...(run.packTitle && run.name ? { when: run.packTitle } : {}) };
211	}
212	
213	/**
214	 * The Connect key, which reports the connection rather than the run behind it.
215	 *
216	 * It is the one key that has something to say while the deck is off, so it
217	 * skips the "Not connected" every other key stops at and names the state it
218	 * is actually in - down by choice, down by the idle timer, or on its way up.
219	 * Once the socket is open it says **Disconnect**, one press away from off -
220	 * which run that carries, if any, is the Run key's business, not this one's.
221	 */
222	export function connectFace(state: DeckState): Face {
223	  if (state.session === "none") return { title: "Sign in", tone: "dim" };
224	  if (state.session === "expired") return { title: "Sign in again", tone: "dim" };
225	  if (!state.on) return { title: "Connect", tone: "dim", when: state.idleOff ? "went idle" : undefined };
226	  if (state.socket !== "open") return { title: "Connecting", tone: "dim" };
227	  return { title: "Disconnect", tone: "deck" };
228	}
229	
230	/**
231	 * When a connection that is holding nothing should close itself.
232	 *
233	 * `since` is when it last had nothing to follow. Null means the clock is not
234	 * running at all - a deck following a live run never times out, however long
235	 * the stream goes, and a deck that is off or still dialing has nothing to
236	 * give up on.
237	 */
238	export function idleDeadline(state: DeckState, since: number): number | null {
239	  if (!state.on || state.socket !== "open" || state.runs.length > 0) return null;
240	  return since + IDLE_OFF_MS;
241	}
242	
243	function flashed(state: DeckState): Face | null {
244	  if (!state.flash || state.flash.ok) return null;
245	  return { title: state.flash.say ?? "No", tone: "refuse" };
246	}
247	
248	/** What the follow key was told about decisions. Re-exported by `actions/next.ts`. */
249	export type NextSettings = { stop?: boolean };
250	
251	/**
252	 * The decision the follow key takes for the streamer, or nothing.
253	 *
254	 * A checklist first, then a declaration with something to suggest: the two
255	 * the page publishes as presets. Placing the key and leaving *Stop at
256	 * decisions* unticked is the streamer choosing to skip the reading, which
257	 * is the rule `apps/web/src/run/handsFree.ts` asks for - a decision is
258	 * skipped only where somebody chose to skip it.
259	 */
260	function decision(offer: Offer, settings: NextSettings): Offer["presets"][number] | null {
261	  if (settings.stop) return null;
262	  const list = offer.presets.find((p) => p.kind === "checklist");
263	  if (list) return list;
264	  return offer.presets.find((p) => p.kind === "declareSubject" && (p.suggestions?.[0] ?? "") !== "") ?? null;
265	}
266	
267	/** What one press of the follow key sends, or nothing for it to send. */
268	export function nextPress(
269	  state: DeckState,
270	  settings: NextSettings,
271	): { press: "primary" } | { press: "answer"; answer: Record<string, string> } | null {
272	  const offer = state.snapshot?.offer;
273	  if (!offer) return null;
274	  if (offer.primary) return { press: "primary" };
275	  const d = decision(offer, settings);
276	  if (!d) return null;
277	  // The words the page takes for each preset, from `takePress.ts`.
278	  return d.kind === "checklist"
279	    ? { press: "answer", answer: { ticks: "all" } }
280	    : { press: "answer", answer: { subject: d.suggestions![0]! } };
281	}
282	
283	export function nextFace(state: DeckState, settings: NextSettings): Face {
284	  const c = common(state) ?? flashed(state);
285	  if (c) return c;
286	  const offer = state.snapshot?.offer;
287	  if (!offer) return { title: "Loading…", tone: "dim" };
288	  if (offer.primary) return { title: offer.primary.label, tone: "live" };
289	  // What the key would take, in the page's own words: the checklist's
290	  // button, or the name it would declare with the ask beneath it.
291	  const d = decision(offer, settings);
292	  if (d?.kind === "checklist") return { title: d.label, tone: "live" };
293	  if (d) return { title: d.suggestions![0]!, tone: "live", when: d.label };
294	  return { title: offer.needsPage ?? "Nothing to press", tone: offer.needsPage ? "refuse" : "dim" };
295	}
296	
297	export function pressFace(state: DeckState, target: PressTarget): Face {
298	  const c = common(state) ?? flashed(state);
299	  if (c) return c;
300	  const offer = state.snapshot?.offer;
301	  if (!offer) return { title: "Loading…", tone: "dim" };
302	  if (target.kind === "roll")
303	    return offer.primary?.id === "roll" ? { title: offer.primary.label, tone: "live" } : { title: "Nothing to roll", tone: "dim" };
304	  if (target.kind === "move") {
305	    const m = offer.moves.find((x) => x.id === target.id);
306	    return m ? { title: m.label, tone: "live" } : { title: "Not on offer", tone: "dim" };
307	  }
308	  const p = offer.presets.find((x) => x.kind === target.preset);
309	  return p ? { title: target.value, tone: "live", when: p.label } : { title: target.value, tone: "dim", when: "Not now" };
310	}
311	
312	/** What the dedicated Roll key says: the waiting roll, in its own words, or nothing to roll. */
313	export function rollFace(state: DeckState): Face {
314	  const c = common(state) ?? flashed(state);
315	  if (c) return c;
316	  const offer = state.snapshot?.offer;
317	  if (!offer) return { title: "Loading…", tone: "dim" };
318	  return offer.primary?.id === "roll"
319	    ? { title: offer.primary.label, tone: "live", when: "Roll" }
320	    : { title: "Nothing to roll", tone: "dim" };
321	}
322	
323	/** What the setup key says: what it applies and hands out, whether that is on offer, or nothing chosen at all. */
324	export function setupFace(state: DeckState, setup?: { id: string; title: string }): Face {
325	  const c = common(state) ?? flashed(state);
326	  if (c) return c;
327	  if (!setup) return { title: "Set up", tone: "dim" };
328	  const offer = state.snapshot?.offer;
329	  if (!offer) return { title: "Loading…", tone: "dim" };
330	  // `?? []`: an older page's offer may not name any setups at all.
331	  return (offer.setups ?? []).some((s) => s.id === setup.id)
332	    ? { title: setup.title, tone: "deck", when: "Apply setup" }
333	    : { title: setup.title, tone: "dim", when: "Not here" };
334	}
335	
336	export function undoFace(state: DeckState): Face {
337	  const c = common(state) ?? flashed(state);
338	  if (c) return c;
339	  const undo = state.snapshot?.offer?.undo;
340	  // The key says "Undo" either way: what it would take back is the run's
341	  // business, and a key too small to read it is no help at the table.
342	  return undo ? { title: "Undo", tone: "undo" } : { title: "Undo", tone: "dim" };
343	}
344	
345	/** Where the Open key points, chosen in its settings. */
346	export type OpenTarget = "run" | "guide" | "rules" | "newrun" | "dock";
347	
348	/** What each page is called on the key, the guide aside. */
349	const OPEN_LABELS: Record<Exclude<OpenTarget, "guide">, string> = {
350	  run: "Open the run",
351	  rules: "Rules",
352	  newrun: "A new run",
353	  dock: "The dock",
354	};
355	
356	/**
357	 * What the Open key says: the page it would put in front of the streamer.
358	 *
359	 * The guide is the one target that needs nothing - no account, no
360	 * connection, no run - so it skips the gating every other key stops at.
361	 * The rest name something the deck is holding, so they say what is missing
362	 * the way the rest of the deck does.
363	 */
364	export function openFace(state: DeckState, target?: OpenTarget): Face {
365	  if (!target) return { title: "Set up", tone: "dim" };
366	  if (target === "guide") return { title: "Guide", tone: "deck", when: "in a browser" };
367	  const c = common(state);
368	  if (c) return c;
369	  return { title: OPEN_LABELS[target], tone: "deck", when: "in a browser" };
370	}
371	
372	export function runFace(state: DeckState): Face {
373	  return common(state) ?? attachedName(state) ?? { title: "Pick a run", tone: "dim" };
374	}
375	
376	/** How far a clock has moved since the snapshot that reported it, in ms. */
377	function clockElapsedMs(c: NonNullable<Snapshot["clocks"]>[number], at: string, now: number): number {
378	  const since = c.status === "running" ? now - Date.parse(at) : 0;
379	  return c.elapsedMs + since;
380	}
381	
382	/** The arithmetic `stream-api.md` publishes, so a key agrees with a widget to the second. */
383	function clockText(c: NonNullable<Snapshot["clocks"]>[number], at: string, now: number): string {
384	  const elapsed = clockElapsedMs(c, at, now);
385	  const ms = c.seconds === null ? elapsed : Math.max(0, c.seconds * 1000 - elapsed);
386	  const s = Math.floor(ms / 1000);
387	  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
388	}
389	
390	export function metricFace(state: DeckState, field: MetricField, now: number): Face {
391	  const c = common(state);
392	  if (c) return c;
393	  const snap = state.snapshot;
394	  if (!snap) return { title: "Loading…", tone: "dim" };
395	  if (field === "score") return { title: snap.score?.text ?? "–", tone: "readout", when: "Score" };
396	  if (field === "unit") return { title: String(snap.unit ?? "–"), tone: "readout", when: snap.words?.unit ?? "Unit" };
397	  if (field === "latest") return { title: snap.latest?.text ?? "–", tone: "readout" };
398	  if (field === "leader") {
399	    const top = snap.standings?.[0];
400	    return top ? { title: top.name, tone: "readout", when: `${top.points} pts` } : { title: "–", tone: "dim", when: "Leader" };
401	  }
402	  if (field === "clock") {
403	    const clock = snap.clocks?.find((x) => x.status === "running") ?? snap.clocks?.[0];
404	    if (!clock || !snap.at) return { title: "–", tone: "dim", when: "Clock" };
405	    const running = clock.kind === "timer" && clock.status === "running" && clock.seconds !== null;
406	    const fraction = running ? clockElapsedMs(clock, snap.at, now) / (clock.seconds! * 1000) : undefined;
407	    return { title: clockText(clock, snap.at, now), tone: "readout", when: clock.label, ...(fraction !== undefined ? { fraction } : {}) };
408	  }
409	  if ("counter" in field) {
410	    const x = snap.counters?.find((k) => k.id === field.counter);
411	    return x ? { title: String(x.value), tone: "readout", when: x.label } : { title: "–", tone: "dim" };
412	  }
413	  const r = snap.resources?.find((k) => k.id === field.resource);
414	  return r
415	    ? { title: r.max === null ? String(r.value) : `${r.value}/${r.max}`, tone: "readout", when: r.label }
416	    : { title: "–", tone: "dim" };
417	}
418	
419	/**
420	 * The tracker a Metric key would move, or nothing where it cannot move one.
421	 *
422	 * Only a counter or a resource: the score, the unit, a clock, the last
423	 * result and the leader are the run's own arithmetic and a key set to one
424	 * of those is a readout. The offer names which trackers the run will take a
425	 * change to, so a key set to a number this run does not keep presses
426	 * nothing rather than being refused on the way out. `?? []` for an older
427	 * page, whose offer names none at all.
428	 */
429	function trackerOf(state: DeckState, field: MetricField | undefined): string | null {
430	  if (!field || typeof field === "string") return null;
431	  const id = "counter" in field ? field.counter : field.resource;
432	  const kind = "counter" in field ? "counter" : "resource";
433	  const offer = state.snapshot?.offer;
434	  return (offer?.trackers ?? []).some((t) => t.id === id && t.kind === kind) ? id : null;
435	}
436	
437	/**
438	 * What one press of a Metric key sends, or nothing for it to send.
439	 *
440	 * A short press does what the key was set to: one up, or straight to a
441	 * number. A hold takes one back off, whichever way it was set, because a
442	 * key that can only count up is a key you have to reach past to the page
443	 * the first time you miscount.
444	 */
445	export function metricPress(
446	  state: DeckState,
447	  field: MetricField | undefined,
448	  press: MetricPress | undefined,
449	  long: boolean,
450	): AnswerPress | null {
451	  const tracker = trackerOf(state, field);
452	  if (!tracker) return null;
453	  if (long) return { press: "answer", answer: { tracker, by: -1 } };
454	  return press?.kind === "set"
455	    ? { press: "answer", answer: { tracker, to: press.value } }
456	    : { press: "answer", answer: { tracker, by: 1 } };
457	}
458	
459	/**
460	 * What the Clock key says: the run's clock, and what pressing it would do.
461	 *
462	 * The same arithmetic a Metric key set to the clock draws, in the tone of a
463	 * key that moves something rather than a readout. A paused clock keeps its
464	 * time on the face and says so underneath; a clock that has run out says
465	 * the same thing the page does.
466	 */
467	export function clockFace(state: DeckState, now: number): Face {
468	  const c = common(state) ?? flashed(state);
469	  if (c) return c;
470	  const snap = state.snapshot;
471	  if (!snap?.offer) return { title: "Loading…", tone: "dim" };
472	  // `?? null` for an older page, which names no clock on its offer at all.
473	  const clock = snap.offer.clock ?? null;
474	  if (!clock) return { title: "No clock", tone: "dim" };
475	  if (clock.status === "done") return { title: "0:00", tone: "dim", when: "done" };
476	  const kept = snap.clocks?.find((x) => x.id === clock.id);
477	  if (!kept || !snap.at) return { title: "–", tone: "dim", when: clock.label };
478	  const text = clockText(kept, snap.at, now);
479	  if (clock.status === "paused") return { title: text, tone: "dim", when: "paused" };
480	  const counting = kept.kind === "timer" && kept.seconds !== null;
481	  const fraction = counting ? clockElapsedMs(kept, snap.at, now) / (kept.seconds! * 1000) : undefined;
482	  return { title: text, tone: "live", when: clock.label, ...(fraction !== undefined ? { fraction } : {}) };
483	}
484	
485	/** What one press of the Clock key sends: the stop on a hold, the pause or the resume on a tap. */
486	export function clockPress(state: DeckState, long: boolean): AnswerPress | null {
487	  const clock = state.snapshot?.offer?.clock;
488	  if (!clock || clock.status === "done") return null;
489	  if (long) return { press: "answer", answer: { clock: clock.id, do: "stop" } };
490	  return { press: "answer", answer: { clock: clock.id, do: clock.status === "running" ? "pause" : "resume" } };
491	}
492	
493	/**
494	 * What the Keep rolling key says: who is throwing the dice.
495	 *
496	 * The same words either way underneath, because twenty characters is not
497	 * room for two different sentences and the key is a switch: what it says on
498	 * top is the state, and pressing it is the other one.
499	 */
500	export function autoRollFace(state: DeckState): Face {
501	  const c = common(state) ?? flashed(state);
502	  if (c) return c;
503	  const offer = state.snapshot?.offer;
504	  if (!offer) return { title: "Loading…", tone: "dim" };
505	  // `?? false` for an older page: a run that says nothing about this is one
506	  // rolling by hand.
507	  return (offer.autoRoll ?? false)
508	    ? { title: "Rolling for you", tone: "live", when: "press to switch" }
509	    : { title: "Roll by hand", tone: "deck", when: "press to switch" };
510	}
511	
512	/** What one press of the Keep rolling key sends: the other setting. */
513	export function autoRollPress(state: DeckState): AnswerPress | null {
514	  const offer = state.snapshot?.offer;
515	  if (!offer) return null;
516	  return { press: "answer", answer: { autoRoll: !(offer.autoRoll ?? false) } };
517	}
518	
519	/**
520	 * What the Finish key says: how the run would end, or that it cannot yet.
521	 *
522	 * The kiln edge, which is the accent for a press there is no coming back
523	 * from, and the hold is the other half of the same guard: a run does not
524	 * end because somebody brushed a key mid-scene.
525	 */
526	export function finishFace(state: DeckState): Face {
527	  const c = common(state) ?? flashed(state);
528	  if (c) return c;
529	  const offer = state.snapshot?.offer;
530	  if (!offer) return { title: "Loading…", tone: "dim" };
531	  // `?? null` for an older page, whose offer says nothing about an ending.
532	  const ending = offer.ending ?? null;
533	  return ending ? { title: ending.label, tone: "refuse", when: "hold to finish" } : { title: "Not yet", tone: "dim" };
534	}
535	
536	/** What a held Finish key sends, or nothing where the run has no ending to take. */
537	export function finishPress(state: DeckState): AnswerPress | null {
538	  return state.snapshot?.offer?.ending ? { press: "answer", answer: { finish: true } } : null;
539	}
