1	import streamDeck, { action, type DialDownEvent, type DialRotateEvent, type KeyDownEvent, type KeyUpEvent } from "@elgato/streamdeck";
2	
3	import { store } from "../plugin.ts";
4	import { metricFace, metricPress, type DeckState, type Face, type MetricField, type MetricPress } from "../state.ts";
5	import { HOLD_MS, HoldTimer, RunlogAction } from "./base.ts";
6	
7	export type MetricSettings = { field?: MetricField; press?: MetricPress };
8	
9	/** The fields a dial cycles through. A counter or resource is the run's own and is not on this wheel. */
10	const FIELDS = ["score", "unit", "clock", "latest", "leader"] as const;
11	
12	/** The field a dial's rotation lands on, wrapping both ways. */
13	export function nextField(field: MetricField, by: number): MetricField {
14	  const i = typeof field === "string" ? FIELDS.indexOf(field) : -1;
15	  return FIELDS[(i + by + FIELDS.length) % FIELDS.length]!;
16	}
17	
18	/**
19	 * A number from the run: the score, the unit, a clock, the last result, the leader.
20	 *
21	 * Set to a counter or a resource it is a key as well as a readout: a tap
22	 * steps the run's own tracker, a hold takes one back off. The five fixed
23	 * fields are the run's arithmetic rather than a number anybody keeps by
24	 * hand, so a press on one of those is refused here rather than sent.
25	 */
26	@action({ UUID: "com.scrthq.runlog.metric" })
27	export class Metric extends RunlogAction<MetricSettings> {
28	  private holds = new HoldTimer();
29	
30	  face(state: DeckState, settings: MetricSettings, now: number): Face {
31	    return settings.field ? metricFace(state, settings.field, now) : { title: "Set up", tone: "dim" };
32	  }
33	
34	  /** The way down is only the start of the clock: this key acts on the way back up. */
35	  override onKeyDown(ev: KeyDownEvent<MetricSettings>): void {
36	    this.holds.down(ev.action.id);
37	  }
38	
39	  override async onKeyUp(ev: KeyUpEvent<MetricSettings>): Promise<void> {
40	    const { field, press } = ev.payload.settings;
41	    const p = metricPress(store.state, field, press, (this.holds.up(ev.action.id) ?? 0) >= HOLD_MS);
42	    if (!p) {
43	      await ev.action.showAlert();
44	      return;
45	    }
46	    await this.send(ev.action, p);
47	  }
48	
