35	      // Five fields every pack has, then whatever counters and resources the
36	      // attached run is keeping - those come from the plugin on every appear.
37	      // A counter or a resource is a key as well as a number, so those two
38	      // are the only fields the press rows are offered for.
39	      (() => {
40	        const { streamDeckClient } = SDPIComponents;
41	        const field = document.getElementById("field");
42	        const press = document.getElementById("press");
43	        const value = document.getElementById("value");
44	        const pressItem = document.getElementById("press-item");
45	        const valueItem = document.getElementById("value-item");
46	        const FIXED = [
47	          ["score", "Score"],
48	          ["unit", "Unit"],
49	          ["clock", "Clock"],
50	          ["latest", "Last result"],
51	          ["leader", "Leader"],
52	        ];
53	        let current = null;
54	        let onPress = { kind: "step" };
55	
56	        const option = (value, label) => {
57	          const o = document.createElement("option");
58	          o.value = JSON.stringify(value);
59	          o.textContent = label;
60	          return o;
61	        };
62	
63	        const fill = (counters, resources) => {
64	          field.replaceChildren(option(null, "Set up"), ...FIXED.map(([v, l]) => option(v, l)));
65	          for (const c of counters) field.appendChild(option({ counter: c.id }, c.label));
66	          for (const r of resources) field.appendChild(option({ resource: r.id }, r.label));
67	          show();
68	        };
69	
70	        const show = () => {
71	          const chosen = JSON.stringify(current ?? null);
72	          const match = [...field.options].find((o) => o.value === chosen);
73	          if (match) field.value = match.value;
74	          // The fixed fields are the run's own arithmetic and take no press.
75	          const adjustable = current !== null && typeof current === "object";
76	          pressItem.hidden = !adjustable;
77	          valueItem.hidden = !adjustable || onPress.kind !== "set";
78	          press.value = onPress.kind;
79	          value.value = onPress.kind === "set" ? String(onPress.value) : "";
80	        };
81	
82	        const save = () => {
83	          streamDeckClient.setSettings(current ? { field: current, press: onPress } : {});
84	          show();
85	        };
86	
87	        field.addEventListener("change", () => {
88	          current = JSON.parse(field.value);
89	          save();
90	        });
91	        press.addEventListener("change", () => {
92	          onPress = press.value === "set" ? { kind: "set", value: Number(value.value) || 0 } : { kind: "step" };
93	          save();
94	        });
95	        value.addEventListener("change", () => {
96	          onPress = { kind: "set", value: Number(value.value) || 0 };
97	          save();
98	        });
99	
100	        streamDeckClient.sendToPropertyInspector.subscribe(({ payload }) => {
101	          if (payload?.t === "fields") fill(payload.counters ?? [], payload.resources ?? []);
102	        });
103	        void streamDeckClient.getSettings().then(({ settings }) => {
104	          current = settings?.field ?? null;
105	          onPress = settings?.press ?? { kind: "step" };
106	          show();
107	        });
108	        fill([], []);
109	      })();
110	    </script>
